function expireSession(){clearPageSession();session='';currentUser=null;signedIn=false;profileItem=null;adminTasks.clear();remoteReady=false;data={reports:data.reports.filter(r=>!r.protected),liked:[],favorites:[],comments:Object.fromEntries(Object.entries(data.comments).map(([id,notes])=>[id,notes.filter(n=>!n.protected)])),guest:'충주시민5624'};remoteMessage='로그인이 만료되었습니다. 다시 로그인해 주세요.';remoteIssue=remoteMessage;updateRemoteBanner();const button=$('.header [data-action=login]');if(button){button.classList.remove('signed-in');button.setAttribute('aria-label','로그인');const label=button.querySelector('span');if(label){label.textContent='로그인';label.removeAttribute('data-no-translate');}button.querySelector('.session-dot')?.remove();}const adminAccount=$('.admin-top-account');if(adminAccount)adminAccount.textContent='로그인 · 가입';}
async function protectedCall(task){try{return await task();}catch(error){if(error.status===401&&session){expireSession();error.message='로그인이 만료되었습니다. 다시 로그인해 주세요. (401)';}throw error;}}
async function recordGet(collection,id,isProtected){return isProtected?protectedCall(()=>getProtectedItem(collection,id,session)):getItem(collection,id);}
async function recordCreate(collection,value,isProtected,visibility='public'){if(!(signedIn&&session)&&!guestProfile?.code)throw new Error('게스트로 시작하거나 로그인해 주세요.');if(isProtected&&!(signedIn&&session))throw new Error('로그인이 필요합니다.');return isProtected?protectedCall(()=>createProtectedItem(collection,value,session,visibility)):createItem(collection,value);}
async function recordUpdate(collection,id,revision,value,isProtected){if(!(signedIn&&session)&&!guestProfile?.code)throw new Error('게스트로 시작하거나 로그인해 주세요.');if(isProtected&&!(signedIn&&session))throw new Error('로그인이 필요합니다.');return isProtected?protectedCall(()=>updateProtectedItem(collection,id,revision,value,session)):updateItem(collection,id,revision,value);}
async function recordDelete(collection,id,revision,isProtected){if(!(signedIn&&session)&&!guestProfile?.code)throw new Error('게스트로 시작하거나 로그인해 주세요.');if(isProtected&&!(signedIn&&session))throw new Error('로그인이 필요합니다.');return isProtected?protectedCall(()=>deleteProtectedItem(collection,id,revision,session)):deleteItem(collection,id,revision);}
