async function refreshRemote({redraw=true}={}){
 if(remoteBusy)return false;remoteBusy=true;remoteMessage='목록을 불러오는 중…';updateRemoteBanner();let sessionExpired=false;
 try {
  if(session&&!currentUser){try{const restored=validateUser(await getCurrentUser(session));if(!restored)throw new Error('로그인 사용자 정보를 확인하지 못했습니다.');currentUser=restored;signedIn=true;}catch(error){if(error.status===401){expireSession();sessionExpired=true;}else throw error;}}
  const keys=['reports','comments','supports','favorites','profiles','rounds'], protectedKeys=['reports','comments','supports','favorites','profiles','updates','admin-tasks'];
  const [values,protectedValues]=await Promise.all([Promise.all(keys.map(key=>listAllItems(collections[key]))),Promise.all(protectedKeys.map(key=>protectedCall(()=>listAllProtectedItems(collections[key],session))))]);
  const lists=Object.fromEntries(keys.map((key,i)=>[key,values[i]])), protectedLists=Object.fromEntries(protectedKeys.map((key,i)=>[key,protectedValues[i]]));
  const result=buildSharedData(lists,clientId,signedIn?currentUser.username:guestProfile?`게스트#${guestProfile.suffix}`:'충주시민5624',protectedLists,currentUser);data=result.data;favoriteItems=result.favoriteItems;
  const reportIds=new Set(data.reports.map(r=>r.id));
  publicUpdates=protectedLists.updates.filter(item=>item?.id&&item?.visibility==='public'&&reportIds.has(item.data?.reportId)&&progressStages.includes(item.data?.stage)&&typeof item.data?.text==='string'&&item.data.text.length>0&&item.data.text.length<=1000).map(item=>({id:item.id,revision:item.revision,reportId:item.data.reportId,stage:item.data.stage,text:item.data.text,author:String(item.owner_name||'회원').slice(0,64),createdAt:item.created_at,reportStatus:item.data.reportStatus,statusSeq:item.data.statusSeq,mine:!!currentUser&&String(item.owner_id)===String(currentUser.id)}));
  applyReportStatuses(data.reports,publicUpdates);
  adminTasks=new Map();if(currentUser)for(const item of protectedLists['admin-tasks']){const task=item?.data;if(item?.visibility==='private'&&String(item.owner_id)===String(currentUser.id)&&reportIds.has(task?.reportId)&&!adminTasks.has(task.reportId)&&priorities.includes(task.priority)&&typeof task.note==='string'&&task.note.length<=1000&&typeof task.due==='string'&&task.due.length<=10)adminTasks.set(task.reportId,{...task,id:item.id,revision:item.revision});}
  profileItem=signedIn?(protectedLists.profiles.find(item=>item?.owner_id!=null&&String(item.owner_id)===String(currentUser.id)&&item?.data&&typeof item.data==='object')||null):(lists.profiles.find(item=>item?.data?.clientId===clientId&&typeof item.data.name==='string'&&item.data.name.length>0&&item.data.name.length<=20&&(typeof item.revision==='number'||typeof item.revision==='string'))||null);
  if(profileItem){const prefs=profileItem.data.preferences;if(prefs&&typeof prefs==='object'){if(languageOptions.some(([code])=>code===prefs.language))language=prefs.language;if(typeof prefs.largeText==='boolean')largeText=prefs.largeText;if(typeof prefs.haptics==='boolean')haptics=prefs.haptics;if(Array.isArray(prefs.compareIds))compareIds=prefs.compareIds.filter(id=>typeof id==='string').slice(0,3);document.body.classList.toggle('large-font',largeText);}}
  roundItem=lists.rounds.find(item=>item?.data&&validRound(item.data)&&(typeof item.revision==='number'||typeof item.revision==='string'))||null;round=roundItem?.data||null;
  remoteReady=true;uncertainActions.clear();remoteMessage=sessionExpired?'로그인이 만료되었습니다. 다시 로그인해 주세요.':result.skipped?`일부 신고 ${result.skipped}건을 읽지 못했습니다.`:'목록이 연결되었습니다.';remoteIssue=sessionExpired||result.skipped?remoteMessage:'';
  compareIds=compareIds.filter(id=>data.reports.some(r=>r.id===id));
  if(redraw&&!$('.modal')){render();if(remoteIssue&&!$('#remote-error'))toast(remoteIssue);}else updateRemoteBanner();return true;
 }catch(error){remoteReady=false;remoteMessage=apiError(error);remoteIssue=remoteMessage;updateRemoteBanner();if(redraw&&!$('.modal')){render();toast(remoteIssue);}return false;}
 finally{remoteBusy=false;}
}
