function cycle(){return `<section class="cycle"><div class="shell cycle-inner"><div class="cycle-left"><span class="cycle-tag">함께 모은 이야기</span><strong>${round?`제 ${round.number}회 시민 공감`:'시민 공감 현황'}</strong><span class="cycle-sep"></span><span class="cycle-period">${round?`${roundDate(round.start)} ~ ${roundDate(round.end)}`:`신고 ${data.reports.length}건 · 공개 공감 집계`}</span></div><div class="cycle-right">${round?`${icon('clock')} <span>마감까지</span> <strong id="round-countdown">${remaining(round.end)}</strong>`:''}<button class="cycle-detail" data-action="rounds">회차 보기 →</button></div></div></section>`;}
function filters(){return `<div class="search-wrap">${icon('search')}<input id="search" type="search" placeholder="동네, 장소, 키워드 검색" value="${esc(state.search)}" aria-label="동네, 장소, 키워드 검색">${state.search?'<button class="search-clear" type="button" data-action="clear-search" aria-label="검색어 지우기">×</button>':''}</div><div class="category-scroll" aria-label="카테고리 필터">${categories.map(c=>`<button data-category="${esc(c)}" class="chip ${state.category===c?'active':''}" aria-pressed="${state.category===c}">${esc(c)}</button>`).join('')}</div><div class="filter-row"><div class="select-wrap">${icon('filter')}<select id="status-filter" aria-label="처리 상태">${statuses.map(s=>`<option value="${esc(s)}" ${state.status===s?'selected':''}>${statusLabel(s)}</option>`).join('')}</select></div><select id="sort" aria-label="정렬"><option value="likes" ${state.sort==='likes'?'selected':''}>공감순</option><option value="recent" ${state.sort==='recent'?'selected':''}>최신순</option></select></div>`;}
function list(){let items=filtered(), ranks=rankMap(); return `<div id="remote-error" class="remote-error" role="status" ${remoteIssue?'':'hidden'}><span data-error-message>${esc(remoteIssue)}</span><button type="button" data-action="reload-remote">다시 불러오기</button></div><div class="list-heading"><div><span class="list-heading-icon">${icon('heart')}</span><strong>이웃들의 이야기</strong></div><span>검색하고 공감해요</span></div>${filters()}<div class="scope-tabs"><button data-scope="all" class="${state.scope==='all'?'active':''}" aria-pressed="${state.scope==='all'}">전체</button><button data-scope="favorites" class="${state.scope==='favorites'?'active':''}" aria-pressed="${state.scope==='favorites'}">관심 신고 <span>${data.favorites.length}</span></button><button data-scope="mine" class="${state.scope==='mine'?'active':''}" aria-pressed="${state.scope==='mine'}">내 신고 <span>${data.reports.filter(r=>r.mine).length}</span></button><button data-scope="liked" class="${state.scope==='liked'?'active':''}" aria-pressed="${state.scope==='liked'}">내 공감 <span>${data.liked.length}</span></button></div><div class="results-title"><strong>시민 공감 민원 <em>${items.length}</em>건</strong>${items.length&&(state.search||state.category!=='전체'||state.status!=='전체 상태'||state.scope!=='all')?'<button class="results-reset" data-action="reset">필터 초기화</button>':'<span>카드를 눌러 지도에서 확인하세요</span>'}</div><div class="cards">${items.length?items.map((r,i)=>card(r,ranks[r.id],i)).join(''):remoteIssue?`<div class="empty"><span>⚠</span><strong>목록을 불러오지 못했어요</strong><p>${esc(remoteIssue)}</p><small>API 서버(www.koosik.kr)에 연결하지 못했습니다. 인터넷 연결을 확인하거나 잠시 후 다시 불러와 주세요.</small><button data-action="reload-remote">다시 불러오기</button></div>`:!remoteReady?'<div class="empty"><strong>신고를 불러오는 중이에요</strong></div>':'<div class="empty"><span>⌕</span><strong>표시할 신고가 없어요</strong><p>다른 검색어나 필터로 다시 찾아보세요.</p><button data-action="reset">필터 초기화</button></div>'}</div>`;}
function mapRankButtons(){const ranks=rankMap();return filtered().filter(r=>ranks[r.id]).sort((a,b)=>ranks[a.id]-ranks[b.id]).map(r=>`<button class="map-rank-${ranks[r.id]}" data-map-rank="${esc(r.id)}" aria-label="${esc(t(`${ranks[r.id]}위`))} · ${esc(r.test?r.title:t(r.title))}"><b>${ranks[r.id]}</b><span>${esc(r.category)}</span></button>`).join('');}
function mapPanel(){return `<div class="map-rank-panel ${mapRankButtons()?'':'hidden'}"><div class="map-rank-heading"><strong>지금 주목받는 이야기</strong><span>공감 모집 중 TOP 3</span></div><div class="map-rank-buttons">${mapRankButtons()}</div></div><div class="map-panel"><div id="map" aria-label="충주시 민원 지도"></div><div class="map-overlay ${mapReady?'hidden':''}" id="map-overlay"><div class="map-error-icon">${icon('map')}</div><strong id="map-error-title">${mapError?'지도를 불러올 수 없어요':'지도를 준비하고 있어요'}</strong><p id="map-error-message">${esc(mapError || '잠시만 기다려 주세요.')}</p><button class="secondary" data-action="retry-map">다시 시도</button><small>목록과 공감 기능은 계속 이용할 수 있어요.</small></div><div class="map-top"><div><span class="map-dot"></span><strong>우리 동네 이야기 지도</strong><span class="map-count">${filtered().length}건 표시</span></div><span class="map-hint">지도 위 위치는 안내용으로 표시됩니다</span></div><div class="map-controls"><button data-action="zoom-in" aria-label="지도 확대">+</button><button data-action="zoom-out" aria-label="지도 축소">−</button><button data-action="fit-results" aria-label="표시된 신고 모두 보기" title="표시된 신고 모두 보기">⤢</button><button data-action="locate" aria-label="내 위치로 이동" title="내 위치로 이동">⌖</button><button data-action="center" aria-label="충주시 중심으로 이동">◎</button></div><div class="map-legend"><span><i class="legend-rank">1</i> 공감 TOP 3</span><span><i></i> 공감모집</span><span><i></i> 다른 상태</span></div></div>`;}

function homeHero(){const open=data.reports.filter(r=>r.status==='공감모집').length;return `<section class="home-hero"><div class="hero-copy"><div class="hero-eyebrow"><span>CHUNGJU ITDA</span><i></i><b>우리 동네 공감 플랫폼</b></div><h1>작은 불편이 모여<br><em>더 좋은 동네로.</em></h1><p>이웃의 이야기를 살펴보고, 함께 공감해요.</p><div class="hero-actions"><button data-page="rank">${icon('spark')} 공감 순위 보기 ${icon('arrow')}</button><span>이야기를 함께 살펴봐요</span></div></div><div class="hero-art"><img src="${neighborhoodVisual}" alt=""><span>우리 동네 일러스트</span></div><div class="hero-stat"><span>함께 살펴볼 이야기</span><strong>${data.reports.length}<small>건</small></strong><i></i><span>공감 모집 중</span><strong>${open}<small>건</small></strong></div></section>`;}
function mapPage(){return `<main class="workspace shell">${homeHero()}<button class="collection-entry" data-page="activity"><span class="collection-entry-icon">✳</span><span><strong>나의 동네 보관함</strong><small>관심·공감·공개 댓글</small></span><b>→</b></button><div class="discovery-actions"><button data-action="compare"><span>⇄</span><div><strong>이야기 비교하기</strong><small>관심 있는 이야기 나란히 보기</small></div><b class="compare-count">${compareIds.length} / 3</b></button><button data-action="discover"><span>✳</span><div><strong>이야기 발견하기</strong><small>새로운 이야기를 만나보세요</small></div><b>↗</b></button></div><div class="explore-heading"><div><span class="eyebrow">EXPLORE THE NEIGHBORHOOD</span><h2>동네 이야기 둘러보기 <span>✳</span></h2><p>목록에서 찾고, 지도에서 위치를 확인해요.</p></div><span class="explore-note">함께 모은 신고</span></div><div class="mobile-switch"><button data-mobile="list" aria-pressed="${state.mobile==='list'}" class="${state.mobile==='list'?'active':''}">${icon('list')} 목록</button><button data-mobile="map" aria-pressed="${state.mobile==='map'}" class="${state.mobile==='map'?'active':''}">${icon('map')} 지도</button></div><div class="workspace-grid"><section class="list-panel ${state.mobile==='map'?'mobile-hidden':''}" data-remote-ready="${remoteReady}" aria-label="민원 목록">${list()}</section><section class="map-column ${state.mobile==='list'?'mobile-hidden':''}">${mapPanel()}</section></div></main>`;}

function ranking(){
 const open=data.reports.filter(r=>r.status==='공감모집').sort((a,b)=>b.likes-a.likes||a.id.localeCompare(b.id));
 const all=[...data.reports].sort((a,b)=>b.likes-a.likes||a.id.localeCompare(b.id));const top=open.slice(0,3);const items=state.rankScope==='open'?open:all;
 return `<main class="subpage shell community-page"><div class="page-intro"><div class="ranking-heading"><div><span class="eyebrow">COMMUNITY RANKING</span><h1>공감이 모이는 이야기</h1><p>우리 동네에서 관심을 받고 있는 신고를 만나보세요.</p></div><button class="round-ghost" data-action="rounds">${icon('clock')} 회차 보기 ${icon('arrow')}</button></div>${pageVisual(communityVisual)}</div><div class="rank-notice"><span>안내</span><p>함께 모은 신고를 기준으로 공감 순위를 보여드려요.</p></div><section class="featured-section"><div class="section-title"><div><span class="section-kicker">THIS ROUND</span><h2>지금 가장 공감하는 신고 <span>TOP 3</span></h2><p>공감 모집 중인 신고의 누적 공감 순위입니다.</p></div><span class="section-count">${open.length}건 참여 중</span></div><div class="featured-grid">${top.length?top.map((r,i)=>`<article class="feature-card feature-${i+1}"><button class="feature-image" data-detail="${esc(r.id)}" aria-label="${esc(r.title)} 자세히 보기"><img src="${esc(imageUrl(r))}" alt="${esc(r.category)} 관련 신고 사진" data-fallback="true"><span class="feature-rank"><small>RANK</small><b>${String(i+1).padStart(2,'0')}</b></span></button><div class="feature-content"><div class="feature-meta"><span>${esc(r.category)}</span><span>공감모집</span>${r.mine?'<span>내 신고</span>':''}</div><button class="feature-title" data-detail="${esc(r.id)}" ${r.test?(r.translatePublic?'data-no-translate data-translate-public':'data-no-translate'):''}>${esc(r.title)}</button><p>${icon('pin')} <span ${r.test?'data-no-translate':''}>${esc(r.location)}</span></p><div class="feature-bottom"><button class="feature-like ${data.liked.includes(r.id)?'liked':''}" data-like="${esc(r.id)}" aria-pressed="${data.liked.includes(r.id)}">${icon('heart')} <strong>${r.likes.toLocaleString()}</strong> <span>공감</span></button><button class="feature-view" data-detail="${esc(r.id)}">자세히 보기 ${icon('arrow')}</button></div></div></article>`).join(''):'<div class="empty">공감 모집 중인 신고가 없습니다.</div>'}</div></section><section class="ranking-board"><div class="section-title board-title"><div><span class="section-kicker">ALL VOICES</span><h2>한눈에 보는 공감 순위</h2><p>마음이 닿은 신고에 공감을 더해 주세요.</p></div><span class="section-count">총 ${items.length}건</span></div><div class="ranking-tabs"><button data-rank-scope="open" class="${state.rankScope==='open'?'active':''}" aria-pressed="${state.rankScope==='open'}">공감 모집 중</button><button data-rank-scope="all" class="${state.rankScope==='all'?'active':''}" aria-pressed="${state.rankScope==='all'}">전체 신고</button></div><div class="ranked-feed">${items.length?items.map((r,i)=>`<article class="ranked-row"><button class="ranked-main" data-detail="${esc(r.id)}"><span class="ranked-index ${i<3?'is-top':''}">${String(i+1).padStart(2,'0')}</span><img src="${esc(imageUrl(r))}" alt="${esc(r.category)} 관련 신고 사진" data-fallback="true"><span class="ranked-copy"><span class="ranked-meta">${esc(r.category)} <i>·</i> ${esc(statusLabel(r.status))} ${r.mine?'· 내 신고':''}</span><strong ${r.test?(r.translatePublic?'data-no-translate data-translate-public':'data-no-translate'):''}>${esc(r.title)}</strong><small ${r.test?'data-no-translate':''}>${esc(r.location)}</small></span></button><button class="ranked-like ${data.liked.includes(r.id)?'liked':''}" data-like="${esc(r.id)}" aria-label="${esc(r.title)} 공감 ${r.likes}건" aria-pressed="${data.liked.includes(r.id)}">${icon('heart')} <strong>${r.likes.toLocaleString()}</strong></button></article>`).join(''):'<div class="empty">표시할 신고가 없어요</div>'}</div></section></main>`;
}
function communityUpdatesFeed(){const recent=publicUpdates.slice(0,6);if(!recent.length)return '';return `<section class="public-feed"><div class="section-title"><div><span class="section-kicker">COMMUNITY UPDATES</span><h2>최근 공유된 진행 의견</h2><p>모든 회원이 작성할 수 있는 공개 의견입니다.</p></div></div><div class="public-feed-list">${recent.map(entry=>{const report=data.reports.find(r=>r.id===entry.reportId);return report?`<button data-detail="${esc(report.id)}"><span>${esc(entry.stage)}</span><strong ${report.test?(report.translatePublic?'data-no-translate data-translate-public':'data-no-translate'):''}>${esc(report.title)}</strong><small data-no-translate data-translate-public>${esc(entry.text)}</small><em data-no-translate>${esc(entry.author)} ↗</em></button>`:''}).join('')}</div></section>`;}
function statusPage(){const total=data.reports.length;return `<main class="subpage shell status-page"><div class="page-intro"><div class="ranking-heading"><div><span class="eyebrow">FOLLOW THE STORY</span><h1>신고의 변화를 살펴봐요</h1><p>목소리가 모인 이후의 단계를 한눈에 확인하세요.</p></div><button class="round-ghost" data-action="report">${icon('plus')} 민원 신고</button></div>${pageVisual(progressVisual)}</div><div class="rank-notice"><span>공유된 신고</span><p>공유된 신고의 진행 단계를 보여드려요.</p></div><div class="status-overview"><div><span>전체 신고</span><strong>${total}<small>건</small></strong><p>함께 모은 신고</p></div><div><span>공감 모집 중</span><strong>${data.reports.filter(r=>r.status==='공감모집').length}<small>건</small></strong><p>함께 관심을 모으는 이야기</p></div><div><span>처리 완료</span><strong>${data.reports.filter(r=>r.status==='처리완료').length}<small>건</small></strong><p>공유된 처리 상태</p></div></div><div class="section-title status-heading"><div><span class="section-kicker">AT A GLANCE</span><h2>단계별 신고 보기</h2><p>단계를 선택하면 해당 신고만 모아볼 수 있어요.</p></div></div><div class="status-grid">${statuses.slice(1).map((st,i)=>`<button data-status-page="${st}"><span class="status-index">0${i+1}</span><span>${statusLabel(st)}</span><strong>${data.reports.filter(r=>r.status===st).length}<small>건</small></strong><span class="status-meter" aria-hidden="true"><i style="width:${total?Math.round(data.reports.filter(r=>r.status===st).length/total*100):0}%"></i></span><span class="status-go">신고 보러가기 →</span></button>`).join('')}</div>${communityUpdatesFeed()}<div class="section-heading status-list-title"><h2>전체 민원</h2><span>총 ${total}건</span></div><div class="status-cards">${[...data.reports].sort((a,b)=>b.likes-a.likes).map(r=>card(r,rankMap()[r.id])).join('')}</div></main>`;}

function pageVisual(src){return `<div class="page-visual"><img src="${src}" alt=""><span>함께하는 충주</span></div>`;}
function infoPage(type){const research=type==='research';return `<main class="subpage shell information"><div class="page-intro"><div class="page-heading"><span class="eyebrow">${research?'LOCAL INSIGHTS':'HOW TO USE'}</span><h1>${research?'자료조사':'이용안내'}</h1><p>${research?'더 나은 충주를 위한 자료를 함께 살펴보세요.':'작은 불편을 이야기하고, 함께 공감해요.'}</p></div>${pageVisual(research?resourcesVisual:guideVisual)}</div>${research?`<div class="info-grid"><article><span>01 / 지역 정보</span><h2>충주시를 알아보세요</h2><p>충주시의 정책과 생활 정보를 확인하고 지역 문제를 살펴볼 수 있습니다.</p><a href="https://www.chungju.go.kr/" target="_blank" rel="noopener noreferrer">충주시청 바로가기 ↗</a></article><article><span>02 / 공공 데이터</span><h2>데이터로 살펴보기</h2><p>공공데이터포털에서 교통, 안전, 환경 등과 관련된 공개 자료를 찾아보세요.</p><a href="https://www.data.go.kr/" target="_blank" rel="noopener noreferrer">공공데이터포털 바로가기 ↗</a></article><article><span>03 / 시민 제안</span><h2>민원 접수 창구</h2><p>행정기관의 답변이나 처리가 필요하다면 민원 창구를 이용해 주세요.</p><a href="https://www.epeople.go.kr/" target="_blank" rel="noopener noreferrer">국민신문고 바로가기 ↗</a></article></div>`:`<div class="info-grid"><article><span>STEP 01</span><h2>동네의 불편을 찾아요</h2><p>민원지도에서 동네, 장소, 키워드로 검색하거나 카테고리를 선택해 보세요.</p></article><article><span>STEP 02</span><h2>마음에 공감을 더해요</h2><p>공감하는 신고의 하트 버튼을 눌러주세요. 로그인하면 계정별로 공감을 저장할 수 있어요. 비회원 공감은 기기 식별 기준입니다.</p></article><article><span>STEP 03</span><h2>새로운 이야기를 남겨요</h2><p>민원 신고 버튼으로 불편을 작성하고 공개 목록에 저장하세요.</p></article></div><div class="notice-box"><strong>꼭 확인해 주세요.</strong><br>긴급 상황은 119 또는 112, 행정 처리가 필요한 민원은 110 또는 국민신문고를 이용해 주세요.</div>`}</main>`;}
function mobileNav(){return `<nav class="mobile-nav" aria-label="모바일 메뉴"><button data-page="map" class="${state.page==='map'?'active':''}" ${state.page==='map'?'aria-current="page"':''}>${icon('map')}<span>동네</span></button><button data-page="rank" class="${state.page==='rank'?'active':''}" ${state.page==='rank'?'aria-current="page"':''}>${icon('podium')}<span>순위</span></button><button class="mobile-create" data-action="report"><span>${icon('plus')}</span><small>신고</small></button><button data-page="status" class="${state.page==='status'?'active':''}" ${state.page==='status'?'aria-current="page"':''}>${icon('progress')}<span>현황</span></button><button data-action="more" class="${['research','guide','activity'].includes(state.page)?'active':''}">${icon('more')}<span>더보기</span></button></nav>`;}
function moreModal(){modal('더 둘러보기',`<div class="more-menu"><p>충주잇다를 더 편하게 이용해보세요.</p><button data-action="compare"><span>⇄</span><div><strong>이야기 비교하기</strong><small>최대 3개를 나란히 살펴봐요</small></div>${icon('arrow')}</button><button data-action="shortcuts"><span>⌘</span><div><strong>빠른 사용법</strong><small>키보드로 편하게 이동하기</small></div>${icon('arrow')}</button><button data-page="activity"><span>${icon('heart')}</span><div><strong>나의 동네 보관함</strong><small>관심·공감·공개 댓글</small></div>${icon('arrow')}</button><button data-page="research"><span>${icon('list')}</span><div><strong>자료조사</strong><small>지역 정보와 민원 창구</small></div>${icon('arrow')}</button><button data-page="guide"><span>${icon('spark')}</span><div><strong>이용안내</strong><small>처음이라면 여기부터</small></div>${icon('arrow')}</button><button data-action="reload-remote"><span>↻</span><div><strong>신고 새로고침</strong><small>최신 목록 불러오기</small></div>${icon('arrow')}</button><button data-action="login"><span>${icon('user')}</span><div><strong>내 계정</strong><small>로그인과 내 활동</small></div>${icon('arrow')}</button></div>`);}
function footer(){return `<footer><div class="shell footer-inner"><div><div class="footer-brand">충주잇다 <span>시민의 일상을 잇다</span></div><div class="footer-links"><button data-action="privacy">개인정보처리방침</button><button data-action="terms">이용약관</button><button data-action="reload-remote">신고 새로고침</button><a href="https://www.chungju.go.kr/" target="_blank" rel="noopener noreferrer">충주시청 ↗</a><a href="https://www.safetyreport.go.kr/" target="_blank" rel="noopener noreferrer">안전신문고 ↗</a><a href="https://www.epeople.go.kr/" target="_blank" rel="noopener noreferrer">국민신문고 ↗</a></div><p>충주잇다는 동네의 이야기를 모으고 살펴보는 공간입니다.<br>긴급 신고 <a href="tel:119">119</a> · <a href="tel:112">112</a> <span>·</span> 일반 민원 상담 <a href="tel:110">110</a></p><small>공개 게시물은 자동 번역을 위해 MyMemory에 전송될 수 있습니다.</small><small>© CHUNGJU EATDA. All rights reserved.</small></div><div class="footer-message">우리의 작은 관심이<br><strong>더 나은 충주를 만듭니다.</strong></div></div></footer>`;}
function adminHeader(){return `<header class="admin-top"><div class="shell admin-top-inner"><div class="admin-brand" aria-label="충주관리 업무 화면">${brandLogo}<strong>충주관리 <small>WORKSPACE</small></strong></div><div><button class="admin-top-account" data-action="login">${signedIn?esc(currentUser.username):guestProfile?esc(`게스트#${guestProfile.suffix}`):'로그인 · 가입'}</button></div></div></header>`;}

function adminView(){return adminPage({data,updates:publicUpdates,tasks:adminTasks,ui:adminUi,signedIn,user:currentUser,guest:guestProfile,remoteReady,remoteIssue,categories,imageUrl,esc});}
function render(){document.body.classList.remove('modal-open');if(pickerMap){pickerMap.remove();pickerMap=null;pickerMarker=null;}document.documentElement.lang=language;if(map){map.remove();map=null;markers=[];mapReady=false;userLocationMarker=null;} clearTimeout(mapTimer); document.title=`${t(({map:'민원지도',rank:'공감순위',status:'처리현황',research:'자료조사',guide:'이용안내',activity:'나의 동네 보관함',admin:'관리 화면'})[state.page])} | ${t('충주잇다')}`; $('#app').innerHTML=(state.page==='admin'?adminHeader():header()+cycle())+(state.page==='admin'?adminView():state.page==='map'?mapPage():state.page==='rank'?ranking():state.page==='status'?statusPage():state.page==='activity'?activityPage({data,tab:state.activityTab,language,esc,t,haptics,statusLabel,signedIn}):infoPage(state.page))+(state.page==='admin'?'':footer()+mobileNav())+'<div id="modal-root"></div><div id="toast" role="status" aria-live="polite"></div>'; if(state.page==='map') initMap(); }
function updateList(){
 const panel=$('.list-panel');if(!panel)return;const oldScroll=panel.scrollTop;
 const search=$('#search',panel),wrap=search?.parentElement;
 if(search&&document.activeElement===search&&wrap?.parentElement===panel){
  // Keep the actual focused input mounted so Korean IME composition and selection are not lost.
  const next=document.createElement('div');next.innerHTML=list();const nextWrap=$('.search-wrap',next);
  const clear=$('.search-clear',wrap),nextClear=$('.search-clear',nextWrap);
  if(clear&&!nextClear)clear.remove();else if(!clear&&nextClear)wrap.appendChild(nextClear);
  [...panel.children].forEach(node=>{if(node!==wrap)node.remove();});
  let before=true;[...next.children].forEach(node=>{if(node===nextWrap){before=false;return;}if(before)panel.insertBefore(node,wrap);else panel.appendChild(node);});
 }else panel.innerHTML=list();
 panel.scrollTop=oldScroll;updateMarkers();const ranks=$('.map-rank-buttons');if(ranks)ranks.innerHTML=mapRankButtons();const rankPanel=$('.map-rank-panel');if(rankPanel)rankPanel.classList.toggle('hidden',!mapRankButtons());const count=$('.map-count');if(count)count.textContent=`${filtered().length}건 표시`;
}
function toast(message){let el=$('#toast'); if(!el)return;el.textContent=t(message);el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),3500);}
function showMapError(message){mapError=message;mapReady=false;const overlay=$('#map-overlay');if(overlay){overlay.classList.remove('hidden');$('#map-error-title').textContent='지도를 불러올 수 없어요';$('#map-error-message').textContent=message;}}
function initMap(){
  const el=$('#map'); if(!el)return;
  try {
    prepareMapWorker();
    if(map){map.remove();map=null;markers=[];} clearTimeout(mapTimer); mapReady=false;mapError='';
    const overlay=$('#map-overlay');overlay?.classList.remove('hidden');$('#map-error-title').textContent='지도를 준비하고 있어요';$('#map-error-message').textContent='실제 지도 데이터를 불러오고 있습니다.';
    const current=map=new maplibregl.Map({container:el,style:mapStyle,center:[center.lng,center.lat],zoom:11,attributionControl:true});
    current.on('load',()=>{if(map!==current)return;clearTimeout(mapTimer);mapReady=true;mapError='';$('#map-overlay')?.classList.add('hidden');updateMarkers();if(state.selected)focusMarker(state.selected);});
    current.on('error',e=>{if(map!==current)return;console.warn('MapLibre:',e.error);const status=e.error?.status;if(!current.isStyleLoaded()||status===403||status===429){clearTimeout(mapTimer);showMapError(status===403||status===429?'지도 제공 서비스가 요청을 제한했습니다. 잠시 후 다시 시도해 주세요.':'지도 데이터에 연결하지 못했습니다. 인터넷 연결이나 브라우저의 콘텐츠 차단 설정을 확인하고 다시 시도해 주세요.');}});
    mapTimer=setTimeout(()=>{if(map===current&&!mapReady)showMapError('지도 응답이 지연되고 있습니다. 인터넷 연결을 확인하고 다시 시도해 주세요.');},15000);
  }catch(e){console.warn('MapLibre:',e);showMapError('지도를 시작하지 못했습니다. 브라우저의 WebGL 지원과 인터넷 연결을 확인하고 다시 시도해 주세요.');}
}
function updateMarkers(){
  if(!mapReady||!map)return;markers.forEach(m=>m.marker.remove());markers=[];const ranks=rankMap();
  filtered().forEach(r=>{const rank=ranks[r.id];const el=document.createElement('button');el.type='button';el.className='map-pin'+(rank?' ranked rank-'+rank:'')+(r.status==='공감모집'?'':' other')+(state.selected===r.id?' selected':'');el.textContent=rank||'';el.dataset.markerId=r.id;el.setAttribute('aria-label',`${rank?t(`${rank}위`)+' · ':''}${r.test?r.title:t(r.title)} · ${t('지도에서 보기')}`);
    const popup=new maplibregl.Popup({offset:24}).setHTML(`<div class="info-window"><div class="popup-tags">${rank?`<span class="popup-rank">${esc(t(`${rank}위`))}</span>`:''}<span>${esc(t(statusLabel(r.status)))}</span></div><b ${r.test?(r.translatePublic?'data-no-translate data-translate-public':'data-no-translate'):''}>${esc(r.test?r.title:t(r.title))}</b><p ${r.test?'data-no-translate':''}>${esc(r.test?r.location:t(r.location))}</p><strong>♥ ${r.likes.toLocaleString()} <small>${esc(t('공감'))}</small></strong>${r.test?`<p>${esc(t('내 기록'))}</p>`:''}<button class="popup-detail" data-detail="${esc(r.id)}">${esc(t('자세히 보기'))} →</button></div>`);
    const marker=new maplibregl.Marker({element:el}).setLngLat([r.lng,r.lat]).setPopup(popup).addTo(map);el.addEventListener('click',()=>{state.selected=r.id;markers.forEach(m=>{m.marker.getElement().classList.toggle('selected',m.id===r.id);if(m.id!==r.id&&m.marker.getPopup().isOpen())m.marker.togglePopup();});document.querySelectorAll('[data-card]').forEach(card=>card.classList.toggle('selected',card.dataset.card===r.id));const card=[...document.querySelectorAll('[data-card]')].find(c=>c.dataset.card===r.id),panel=$('.list-panel');if(card&&panel&&innerWidth>800)panel.scrollTo({top:panel.scrollTop+card.getBoundingClientRect().top-panel.getBoundingClientRect().top-15,behavior:'smooth'});});markers.push({id:r.id,marker});
  });
}

function focusMarker(id){const r=data.reports.find(x=>x.id===id);if(!r||!mapReady||!map)return;map.resize();map.flyTo({center:[r.lng,r.lat],zoom:15});const found=markers.find(m=>m.id===id);if(found&&!found.marker.getPopup().isOpen())found.marker.togglePopup();}
function locateUser(){
 if(!mapReady||!map){toast('지도를 먼저 연결해 주세요.');return;}
 if(!navigator.geolocation){toast('이 브라우저에서는 위치 확인을 지원하지 않아요.');return;}
 const current=map;toast('기기 위치를 확인하고 있어요.');
 try{navigator.geolocation.getCurrentPosition(position=>{
  if(map!==current||!mapReady)return;
  const {latitude,longitude}=position.coords;if(!Number.isFinite(latitude)||!Number.isFinite(longitude))return;
  if(userLocationMarker)userLocationMarker.remove();const el=document.createElement('div');el.className='user-location-marker';el.setAttribute('role','img');el.setAttribute('aria-label',t('내 위치'));
  userLocationMarker=new maplibregl.Marker({element:el}).setLngLat([longitude,latitude]).addTo(map);map.flyTo({center:[longitude,latitude],zoom:14});toast('내 위치로 이동했어요. 위치는 저장하지 않아요.');
 },()=>{if(map===current)toast('위치 권한과 기기 설정을 확인해 주세요.');},{enableHighAccuracy:false,timeout:10000,maximumAge:60000});}catch{toast('위치 권한과 기기 설정을 확인해 주세요.');}
}
function fitResults(){if(!mapReady||!map){toast('지도를 먼저 연결해 주세요.');return;}const items=filtered();if(!items.length){toast('지도에 표시할 신고가 없어요.');return;}map.resize();if(items.length===1){map.flyTo({center:[items[0].lng,items[0].lat],zoom:14});return;}const bounds=new maplibregl.LngLatBounds();items.forEach(r=>bounds.extend([r.lng,r.lat]));map.fitBounds(bounds,{padding:70,maxZoom:14});}
function selectReport(id){let r=data.reports.find(x=>x.id===id);if(!r)return;const filterReset=state.page==='map'&&!filtered().some(item=>item.id===id);if(filterReset){state.category='전체';state.status='전체 상태';state.search='';state.scope='all';}state.selected=id;if(state.page!=='map'){writeRoute('map');state.page='map';state.category='전체';state.status='전체 상태';state.search='';state.scope='all';state.mobile='map';render();requestAnimationFrame(()=>$('.map-column')?.scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'}));} else {updateList();if(innerWidth<=800){state.mobile='map';$('.list-panel')?.classList.add('mobile-hidden');$('.map-column')?.classList.remove('mobile-hidden');document.querySelectorAll('[data-mobile]').forEach(b=>{const active=b.dataset.mobile==='map';b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active));});$('.map-column')?.scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});}focusMarker(id);if(!mapReady)toast('지도를 불러온 후 위치를 확인할 수 있어요.');else if(filterReset)toast('필터를 초기화하고 선택한 위치를 보여드려요.');}}

let modalPreviousFocus=null, pendingLoginIntent=null;
function requireSignIn(intent){if((signedIn&&session)||guestProfile?.code)return true;if(guestAuthBusy||guestRestoreBusy){toast('게스트 정보를 확인하고 있어요. 잠시만 기다려 주세요.');return false;}pendingLoginIntent=intent;loginModal();const status=$('#auth-api-status');if(status)status.textContent='로그인하거나 가입한 뒤 이용할 수 있어요.';return false;}
function resumeLoginIntent(intent){if(!intent)return;if(intent.type==='report')reportModal(intent.id);else if(intent.type==='round')roundModal();else if(intent.id&&data.reports.some(r=>r.id===intent.id)){detailModal(intent.id);if(intent.type==='comment')setTimeout(()=>$('#note-form input')?.focus(),0);else toast('로그인했어요. 원하시는 버튼을 다시 눌러 주세요.');}}
function modal(title,content){if(!$('.modal'))modalPreviousFocus=document.activeElement;document.body.classList.add('modal-open');if(pickerMap){pickerMap.remove();pickerMap=null;pickerMarker=null;}delete $('#modal-root').dataset.openDetail;delete $('#modal-root').dataset.roundOpen;delete $('#modal-root').dataset.compareOpen;$('#modal-root').innerHTML=`<div class="modal-backdrop" data-action="close-modal"><section class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-head"><h2>${esc(title)}</h2><button data-action="close-modal" aria-label="닫기">×</button></div>${content}</section></div>`;setTimeout(()=>$('.modal input, .modal select, .modal button')?.focus({preventScroll:true}),0);}
function loginModal(mode='login',name='',member=false){
 if(signedIn){modal('내 계정',`<div class="login-intro"><span class="login-avatar">${icon('user')}</span><div><h3 data-no-translate>${esc(currentUser.username)}</h3><p>로그인 중</p></div></div><p class="field-help">내 신고와 관심 목록, 설정을 계정으로 관리합니다. 공개 신고·댓글과 사진은 다른 방문자에게 보입니다.</p>${state.page==='admin'?'':`<div class="owner-actions"><button data-profile-scope="mine">내 신고 보기</button><button data-profile-scope="favorites">관심 신고 보기</button></div>`}<p id="auth-api-status" role="status"></p><button class="secondary full" data-action="logout">로그아웃</button>`);return;}
 if(!member&&(state.page!=='admin'||guestProfile?.code)){if(guestProfile?.code)guestAccountModal();else guestNameModal();return;}
 authMode=mode;modal(mode==='signup'?'회원가입':'로그인',`<div class="login-intro"><span class="login-avatar">${icon('user')}</span><div><h3>${mode==='signup'?'함께 시작해요':'다시 만나서 반가워요'}</h3><p>${state.page==='admin'?'업무 기록을 이어서 확인하세요.':'어디서든 내 활동을 이어가요.'}</p></div></div><form id="auth-form" data-mode="${mode}"><label>아이디<input name="username" required minlength="3" maxlength="64" autocomplete="username" value="${esc(name)}" placeholder="한글·영문·숫자 3~64자"></label><label>비밀번호<input name="password" type="password" required minlength="8" maxlength="128" autocomplete="${mode==='signup'?'new-password':'current-password'}" placeholder="8~128자"></label>${mode==='signup'?'<label>비밀번호 확인<input name="confirm" type="password" required minlength="8" maxlength="128" autocomplete="new-password"></label>':''}<p class="field-help">아이디는 한글·영문·숫자로 시작하고 . _ @ - 를 사용할 수 있어요.</p><p id="auth-api-status" class="report-api-status" role="status" aria-live="polite"></p><button class="primary full" type="submit">${mode==='signup'?'가입하고 시작하기':'로그인'}</button><button class="secondary full" type="button" data-action="auth-mode">${mode==='signup'?'이미 계정이 있나요? 로그인':'처음 오셨나요? 회원가입'}</button><button class="secondary full" type="button" data-action="guest-name">${guestProfile?'게스트 이름 변경':'게스트로 시작하기'}</button></form>`);
}
