window.addEventListener('storage',event=>{if(event.key!=='chungju_guest'||event.newValue!==null||!guestProfile)return;clearGuestState();if(signedIn)return;const button=$('.header [data-action=login]');if(button){button.setAttribute('aria-label','로그인');const label=button.querySelector('span');if(label){label.textContent='로그인';label.removeAttribute('data-no-translate');}}const status=$('#report-api-status')||$('#comment-api-status');if(status)status.textContent='다른 탭에서 게스트 로그아웃되었습니다. 입력은 유지됩니다.';if(!$('.modal'))render();toast('다른 탭에서 게스트 로그아웃되었어요.');});

