function exportAdminCsv(){const csvCell=value=>{let text=String(value??'');if(/^[\s\x00-\x1f]*[=+@-]/.test(text))text="'"+text;return '"'+text.replaceAll('"','""')+'"';};const rows=[['제목','분류','위치','상세 내용','공감','댓글','최근 공개 진행 의견'],...filteredAdmin({data,updates:publicUpdates,tasks:adminTasks,ui:adminUi}).map(r=>[r.title,r.category,r.location,r.detail,r.likes,(data.comments[r.id]||[]).length,publicUpdates.find(u=>u.reportId===r.id)?.stage||'미기록'])];const blob=new Blob(['\ufeff'+rows.map(row=>row.map(csvCell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='chungju-reports.csv';document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('현재 필터의 신고 목록을 내보냈어요.');}
let adminBusy=false;
