function adminRefresh(clearId=''){
 const old=$('.admin-page');if(!old)return;const account=$('.admin-top-account');if(account)account.textContent=signedIn?currentUser.username:guestProfile?`게스트#${guestProfile.suffix}`:'로그인 · 가입';const saved=[...old.querySelectorAll('form')].filter(f=>f.id!==clearId&&(f.dataset.dirty||f.dataset.uncertain)).map(f=>({id:f.id,report:f.dataset.report,values:[...f.querySelectorAll('input[name],select[name],textarea[name]')].map(el=>({name:el.name,value:el.value,checked:el.checked,type:el.type})),dataset:{...f.dataset},status:$('.admin-form-status',f)?.textContent||'',check:!!f.querySelector('[data-action^=check-admin]:not([hidden])')}));
 const scroll=window.scrollY;old.outerHTML=adminView();
 for(const draft of saved){const form=document.getElementById(draft.id);if(!form||form.dataset.report!==draft.report)continue;for(const item of draft.values){const field=form.elements.namedItem(item.name);if(field){if(item.type==='checkbox'||item.type==='radio')field.checked=item.checked;else field.value=item.value;}}Object.assign(form.dataset,draft.dataset);const status=$('.admin-form-status',form);if(status)status.textContent=draft.status;const check=form.querySelector('[data-action^=check-admin]');if(check)check.hidden=!draft.check;const submit=form.querySelector('[type=submit]');if(submit)submit.disabled=!!form.dataset.uncertain;}
 window.scrollTo(0,scroll);
}
