  const latest=await protectedCall(()=>getProtectedItem(collections.updates,form.dataset.id,session));assertNoPasswordFields(latest.data);
  if(String(latest.owner_id)!==String(currentUser?.id))throw new Error('본인이 작성한 기록만 수정할 수 있습니다.');
  if(String(latest.revision)!==form.dataset.revision){form.dataset.revision=String(latest.revision);status.textContent=`다른 변경이 있습니다. 최신 기록: ${String(latest.data?.stage||'')} · ${String(latest.data?.text||'').slice(0,120)}. 입력 내용은 유지됩니다. 확인 후 다시 저장해 주세요.`;return;}
