 const fd=new FormData(form),priority=String(fd.get('priority')||''),due=String(fd.get('due')||''),workState=String(fd.get('workState')||''),tags=String(fd.get('tags')||'').trim(),checklist={reviewed:fd.has('reviewed'),locationChecked:fd.has('locationChecked'),replied:fd.has('replied')},note=String(fd.get('note')||'').trim(),status=$('.admin-form-status',form);if(!priorities.includes(priority)||!workStates.includes(workState)||tags.length>120||note.length>1000||(due&&!/^\d{4}-\d{2}-\d{2}$/.test(due))){status.textContent='입력 내용을 확인해 주세요.';return;}
 const op=operationId(),button=form.querySelector('[type=submit]');adminBusy=true;button.disabled=true;status.textContent='저장 중…';let writing=false;
