   status.textContent='신고 내용을 저장하고 있어요…';creating=true;
   if(existing)await recordUpdate(collections.reports,existing.rawId,latest.revision,{...latest.data,...fields},existing.protected);else await recordCreate(collections.reports,{...fields,...(!signedIn?{clientId,author:data.guest}:{}),status:'공감모집'},form.dataset.protected==='true','public');
   form.dataset.submitted='true';if(!existing)clearDraft();reportSending=false;closeModal();state.page='map';writeRoute('map');state.category='전체';state.status='전체 상태';state.search='';state.scope='all';state.sort='recent';state.mobile='list';await refreshRemote();toast('공개 신고를 저장했어요.');
