document.addEventListener('error',e=>{if(e.target.matches?.('img[data-fallback]')){e.target.removeAttribute('data-fallback');e.target.src=stationPhoto;}},true);
function showTranslationFailure(target){if(language!==target||translationFailureLanguage===target)return;translationFailureLanguage=target;toast('일부 번역을 불러오지 못해 원문을 표시합니다.');}
function translatePublicPage(root){
 if(!root||state.page==='admin')return;
 const visit=node=>{
  if(node.nodeType!==Node.TEXT_NODE)return;const parent=node.parentElement;
  if(!parent||!parent.closest('[data-translate-public]')||parent.closest('script,style,textarea,input,select,form,[contenteditable=true],#toast,.maplibregl-ctrl-attrib,[role=status],.activity-items,.compare-grid'))return;
  const raw=node.nodeValue;if(!raw||raw.trim().length<2||!/[\p{L}]/u.test(raw)||raw.length>1400)return;
  if(language==='ko'&&/[가-힣]/.test(raw)&&!/[ぁ-ヿ㐀-鿿ก-๿Ѐ-ӿក-៿A-Za-z]/.test(raw))return;
  const previous=translationNodes.get(node);if(previous&&previous.target===language&&(raw===previous.raw||raw===previous.output))return;
  const target=language,record={raw,target,output:null};translationNodes.set(node,record);
  translatePublicRemote(raw,target).then(result=>{if(state.page==='admin'||language!==target||!node.isConnected||node.nodeValue!==raw)return;record.output=result;node.nodeValue=result;}).catch(()=>showTranslationFailure(target));
 };
 if(root.nodeType===Node.TEXT_NODE)visit(root);else if(root.nodeType===Node.ELEMENT_NODE){const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);while(walker.nextNode())visit(walker.currentNode);}
}
const translationObserver=new MutationObserver(records=>{for(const record of records){const nodes=record.type==='characterData'?[record.target]:record.addedNodes;for(const node of nodes){if(language!=='ko')translateElement(node,language);translatePublicPage(node);}}});
translationObserver.observe($('#app'),{childList:true,subtree:true,characterData:true});
